command:
set -euo pipefail
expected=2f9fa1004ab140eb312302f799bf2e6165c4aff6
[[ "$(hostname)" == andreas-MACO && "$(id -un)" == andreas ]] || { echo SUBJECT_MISMATCH >&2; exit 81; }
[[ "$(git rev-parse HEAD)" == "$expected" ]] || { echo HEAD_MISMATCH >&2; exit 82; }
[[ -z "$(git status --porcelain=v1 --untracked-files=no)" ]] || { echo TRACKED_WORKTREE_DIRTY >&2; exit 83; }
manifest=/var/lib/entityos/data/volatile-state-rescue/fred-20260913T0246p0700/MANIFEST.json
sudo -n test -f "$manifest" || { echo RESCUE_MANIFEST_MISSING >&2; exit 84; }
sudo -n python3 -c 'import json,sys; p=json.load(open(sys.argv[1])); assert p.get("result")=="RESCUE_SNAPSHOT_VERIFIED"; assert p.get("database_count")==6; assert p.get("required_observed_set_complete") is True' "$manifest"
dropins=$(systemctl show entityos-vm.service -p DropInPaths --value)
[[ "$dropins" == *'/etc/systemd/system/entityos-vm.service.d/10-volatile-state-guard.conf'* && "$dropins" == *'/etc/systemd/system/entityos-vm.service.d/20-semantic-state-cutover.conf'* ]] || { echo DROPIN_MISMATCH >&2; exit 85; }
[[ -z "$(systemctl show entityos-vm.service -p ExecStopPost --value)" ]] || { echo EXECSTOPPOST_NOT_EMPTY >&2; exit 86; }
state=$(systemctl show entityos-vm.service -p ActiveState --value)
pid=$(systemctl show entityos-vm.service -p MainPID --value)
epoch=$(systemctl show entityos-vm.service -p ActiveEnterTimestamp --value)
[[ "$state" == active && "$pid" =~ ^[1-9][0-9]*$ ]] || { echo VM_NOT_ACTIVE >&2; exit 87; }
echo "PRE_STOP state=$state pid=$pid epoch=$epoch rescue_manifest=$manifest"
sudo -n systemctl stop entityos-vm.service
post=$(systemctl show entityos-vm.service -p ActiveState --value)
[[ "$post" == inactive || "$post" == failed ]] || { echo "STOP_POST_BAD state=$post" >&2; exit 88; }
for f in /var/lib/entityos/rootfs-run/root/.local/share/agentzero/consciousness.db /var/lib/entityos/rootfs-run/root/.local/share/agentzero/unified.db /var/lib/entityos/rootfs-run/root/.local/share/agentzero/welt.db /var/lib/entityos/rootfs-run/root/.local/share/frank/db/amygdala.db /var/lib/entityos/rootfs-run/root/.local/share/frank/db/world_experience.db /var/lib/entityos/rootfs-run/root/.local/share/frank/db/world_experience.db.vor-maerz-20260910; do sudo -n test -f "$f" || { echo "SOURCE_LOST_AFTER_STOP $f" >&2; exit 89; }; sudo -n stat -c 'PRESERVED %n bytes=%s' "$f"; done
echo "POST_STOP state=$post ROOTFS_PRESERVED=1 NO_RESTART=1"
